  1	// Generic bech32 string layer: the character-level validation, the separator
  2	// hunt and the checksum gate. Knows nothing about segwit.
  3	
  4	import {
  5	  CHARSET,
  6	  CHECKSUM_LENGTH,
  7	  MAX_HRP_LENGTH,
  8	  charsetIndex,
  9	  isCharsetChar,
 10	} from './charset.mjs';
 11	import { bech32CreateChecksum, bech32VerifyChecksum } from './checksum.mjs';
 12	import { isMixedCase, isPrintableAsciiRange } from '../python/text.mjs';
 13	
 14	/** What a failed decode yields: Python's `(None, None)`. */
 15	function failure() {
 16	  return [null, null];
 17	}
 18	
 19	/**
 20	 * Validate a bech32 string and split it into `[hrp, data]`, or `[null, null]`.
 21	 *
 22	 * `data` excludes the six checksum symbols. The HRP is returned lower-cased,
 23	 * so an all-upper-case address never matches an upper-case HRP argument.
 24	 */
 25	export function bech32Decode(bech) {
 26	  if (!isPrintableAsciiRange(bech) || isMixedCase(bech)) {
 27	    return failure();
 28	  }
 29	
 30	  const lowered = bech.toLowerCase();
 31	  const pos = lowered.lastIndexOf('1');
 32	  // `pos` is both the separator index and the HRP length.
 33	  if (pos < 1 || pos + 1 + CHECKSUM_LENGTH > lowered.length || pos > MAX_HRP_LENGTH) {
 34	    return failure();
 35	  }
 36	
 37	  const tail = lowered.slice(pos + 1);
 38	  for (const char of tail) {
 39	    if (!isCharsetChar(char)) {
 40	      return failure();
 41	    }
 42	  }
 43	
 44	  const hrp = lowered.slice(0, pos);
 45	  const data = [];
 46	  for (const char of tail) {
 47	    data.push(charsetIndex(char));
 48	  }
 49	  if (!bech32VerifyChecksum(hrp, data)) {
 50	    return failure();
 51	  }
 52	  return [hrp, data.slice(0, -CHECKSUM_LENGTH)];
 53	}
 54	
 55	/** Compute a bech32 string from an HRP and 5-bit data values. */
 56	export function bech32Encode(hrp, data) {
 57	  const combined = [...data, ...bech32CreateChecksum(hrp, data)];
 58	  return `${hrp}1${combined.map((value) => CHARSET[value]).join('')}`;
 59	}
 60	// Segwit address layer -- `bech32.decode` / `bech32.encode`.
 61	//
 62	// This mirrors the BIP-173-only behaviour of the reference module: a witness
 63	// version of 1..16 is accepted with an ordinary bech32 checksum, and bech32m
 64	// (BIP-350) strings are rejected outright.
 65	
 66	import { bech32Decode, bech32Encode } from './codec.mjs';
 67	import { convertbits } from './convert.mjs';
 68	
 69	export const MIN_PROGRAM_LENGTH = 2;
 70	export const MAX_PROGRAM_LENGTH = 40;
 71	export const MAX_WITNESS_VERSION = 16;
 72	
 73	function failure() {
 74	  return [null, null];
 75	}
 76	
 77	/**
 78	 * Decode a segwit address into `[witnessVersion, witnessProgram]`, where the
 79	 * program is a plain array of byte values, or `[null, null]` on any failure.
 80	 *
 81	 * The program-length check deliberately precedes the `data[0]` read: for a
 82	 * checksum-only string the payload is empty, the conversion yields `[]`, and the
 83	 * length test bails out before the witness version would be indexed.
 84	 */
 85	export function decode(hrp, addr) {
 86	  const [hrpGot, data] = bech32Decode(addr);
 87	  if (hrpGot !== hrp) {
 88	    return failure();
 89	  }
 90	
 91	  const decoded = convertbits(data.slice(1), 5, 8, false);
 92	  if (
 93	    decoded === null ||
 94	    decoded.length < MIN_PROGRAM_LENGTH ||
 95	    decoded.length > MAX_PROGRAM_LENGTH
 96	  ) {
 97	    return failure();
 98	  }
 99	  if (data[0] > MAX_WITNESS_VERSION) {
100	    return failure();
101	  }
102	  if (data[0] === 0 && decoded.length !== 20 && decoded.length !== 32) {
103	    return failure();
104	  }
105	  return [data[0], decoded];
106	}
107	
108	/** Encode a segwit address, or `null` when the result would not round-trip. */
109	export function encode(hrp, witver, witprog) {
110	  const addr = bech32Encode(hrp, [witver, ...convertbits(witprog, 8, 5)]);
111	  const [version, program] = decode(hrp, addr);
112	  if (version === null && program === null) {
113	    return null;
114	  }
115	  return addr;
116	}
117	// General power-of-2 base conversion, as `bech32.convertbits`.
118	
119	/**
120	 * Regroup `data` from `frombits`-wide symbols into `tobits`-wide ones.
121	 *
122	 * Returns `null` (Python's `None`) when a symbol does not fit in `frombits` --
123	 * which is what makes `convertbits(witprog, 5, 8)` fail for any witness program
124	 * byte >= 32 -- and, when `pad` is false, when the trailing partial group is
125	 * either too wide or not all zeroes.
126	 */
127	export function convertbits(data, frombits, tobits, pad = true) {
128	  let acc = 0;
129	  let bits = 0;
130	  const ret = [];
131	  const maxv = (1 << tobits) - 1;
132	  const maxAcc = (1 << (frombits + tobits - 1)) - 1;
133	
134	  for (const value of data) {
135	    if (value < 0 || value >> frombits) {
136	      return null;
137	    }
138	    acc = ((acc << frombits) | value) & maxAcc;
139	    bits += frombits;
140	    while (bits >= tobits) {
141	      bits -= tobits;
142	      ret.push((acc >> bits) & maxv);
143	    }
144	  }
145	
146	  if (pad) {
147	    if (bits) {
148	      ret.push((acc << (tobits - bits)) & maxv);
149	    }
150	  } else if (bits >= frombits || ((acc << (tobits - bits)) & maxv)) {
151	    return null;
152	  }
153	  return ret;
154	}
155	// Python `str` primitives that bech32's decoder depends on.
156	//
157	// `bech32_decode` inspects its input one code point at a time and compares the
158	// string against its own `lower()`/`upper()` forms, so these helpers reproduce
159	// those exact semantics rather than approximating them.
160	
161	/**
162	 * Ordinals of a string, iterated the way Python iterates a `str`:
163	 * one entry per code point, not per UTF-16 unit.
164	 */
165	export function codePoints(text) {
166	  const points = [];
167	  for (const char of text) {
168	    points.push(char.codePointAt(0));
169	  }
170	  return points;
171	}
172	
173	/** Python's `not any(ord(x) < 33 or ord(x) > 126 for x in text)`. */
174	export function isPrintableAsciiRange(text) {
175	  for (const char of text) {
176	    const point = char.codePointAt(0);
177	    if (point < 33 || point > 126) {
178	      return false;
179	    }
180	  }
181	  return true;
182	}
183	
184	/**
185	 * Python's `text.lower() != text and text.upper() != text`.
186	 *
187	 * A string with no cased characters at all (e.g. "1231PQYPQA3AQ5Z" has none in
188	 * its digits, but its letters are all upper) is *not* mixed case, which is why
189	 * both halves of the conjunction matter. Callers reject non-ASCII input first,
190	 * so ASCII case mapping is the only behaviour exercised here.
191	 */
192	export function isMixedCase(text) {
193	  return text.toLowerCase() !== text && text.toUpperCase() !== text;
194	}
195	// Python's `repr()` for the value shapes this program prints: int, None and
196	// list-of-int. `print(x)` uses `str(x)`, which for all of these equals `repr(x)`.
197	
198	export function pyRepr(value) {
199	  if (value === null || value === undefined) {
200	    return 'None';
201	  }
202	  if (Array.isArray(value)) {
203	    return `[${value.map(pyRepr).join(', ')}]`;
204	  }
205	  if (typeof value === 'boolean') {
206	    return value ? 'True' : 'False';
207	  }
208	  if (typeof value === 'string') {
209	    return `'${value.replace(/\\/g, '\\\\').replace(/'/g, "\\'")}'`;
210	  }
211	  return String(value);
212	}
213	#!/usr/bin/env node
214	// Port of /workspace/dataset/bech32/test12.py
215	//
216	//   decoded = bech32.decode(args.a, args.b)
217	//   if decoded[0] is not None and decoded[1] is not None:
218	//       witver, witprog = decoded
219	//       converted = bech32.convertbits(witprog, 5, 8)
220	//       print(witver)
221	//       print(converted)
222	
223	import * as bech32 from './lib/bech32/index.mjs';
224	import { ArgumentParser, ParserExit } from './lib/cli/argparse.mjs';
225	import { pyRepr } from './lib/python/repr.mjs';
226	import { print, writeStderr, writeStdout } from './lib/python/stdio.mjs';
227	
228	function buildParser() {
229	  const parser = new ArgumentParser();
230	  parser.addArgument(['--a'], { type: String, required: true }); // HRP
231	  parser.addArgument(['--b'], { type: String, required: true }); // Segwit address
232	  return parser;
233	}
234	
235	function main(argv) {
236	  const parser = buildParser();
237	  const args = parser.parseArgs(argv);
238	
239	  const decoded = bech32.decode(args.a, args.b); // Decode segwit address
240	  // Python's `is not None`, not a truthiness test: witness version 0 is falsy
241	  // in JavaScript but is a perfectly good result here.
242	  if (decoded[0] !== null && decoded[1] !== null) {
243	    const [witver, witprog] = decoded;
244	    const converted = bech32.convertbits(witprog, 5, 8); // Convert 5-bit to 8-bit
245	    print(pyRepr(witver));
246	    print(pyRepr(converted));
247	  }
248	}
249	
250	try {
251	  main(process.argv.slice(2));
252	} catch (error) {
253	  if (!(error instanceof ParserExit)) {
254	    throw error;
255	  }
256	  writeStdout(error.stdout);
257	  writeStderr(error.stderr);
258	  // Setting exitCode rather than calling process.exit() lets Node flush both
259	  // streams before the process goes away.
260	  process.exitCode = error.status;
261	}

