// Emits /tmp/corpus/official-vectors.json -- the published BIP-173 and BIP-350
// test vectors, each tried against the correct hrp and against wrong hrps.
import { writeFileSync, mkdirSync } from 'node:fs';

// ---------------------------------------------------------------- BIP-173 ----
// Valid bech32 strings (raw, not segwit addresses). All confirmed byte-for-byte
// against the reference encoder in /tmp/probe/gen.mjs.
const B173_VALID_BECH32 = [
  'A12UEL5L',
  'a12uel5l',
  'an83characterlonghumanreadablepartthatcontainsthenumber1andtheexcludedcharactersbio1tt5tgs',
  'abcdef1qpzry9x8gf2tvdw0s3jn54khce6mua7lmqqqxw',
  '11qqqqqqqqqqqqqqqqqqqqqqqqqqqqqqqqqqqqqqqqqqqqqqqqqqqqqqqqqqqqqqqqqqqqqqqqqqqqqqqqqqc8247j',
  'split1checkupstagehandshakeupstreamerranterredcaperred2y9e3w',
  '?1ezyfcl',
];

// Invalid bech32 strings, with the BIP's stated reason.
const B173_INVALID_BECH32 = [
  ' 1nwldj5',   // HRP character out of range (0x20)
  '1axkwrx',   // HRP character out of range (0x7f)
  '1eym55h',   // HRP character out of range (0x80)
  'an84characterslonghumanreadablepartthatcontainsthenumber1andtheexcludedcharactersbio1569pvx',
  'pzry9x0s0muk',    // no separator
  '1pzry9x0s0muk',   // empty HRP
  'x1b4n0q5v',       // invalid data character
  'li1dgmt3',        // too short checksum
  'de1lg7wtÿ',  // invalid character in checksum
  'A1G7SGD8',        // checksum computed over uppercase HRP
  '10a06t8',         // empty HRP
  '1qzzfhee',        // empty HRP
];

// Valid segwit addresses. [address, declared hrp]
const B173_VALID_ADDR = [
  ['BC1QW508D6QEJXTDG4Y5R3ZARVARY0C5XW7KV8F3T4', 'bc'],
  ['tb1qrp33g0q5c5txsp9arysrx4k6zdkfs4nce4xj0gdcccefvpysxf3q0sl5k7', 'tb'],
  ['bc1pw508d6qejxtdg4y5r3zarvary0c5xw7kw508d6qejxtdg4y5r3zarvary0c5xw7k7grplx', 'bc'],
  ['BC1SW50QA3JX3S', 'bc'],
  ['bc1zw508d6qejxtdg4y5r3zarvaryvg6kdaj', 'bc'],
  ['tb1qqqqqp399et2xygdj5xreqhjjvcmzhxw4aywxecjdzew6hylgvsesrxh6hy', 'tb'],
];

// Invalid segwit addresses. [address, declared hrp]
const B173_INVALID_ADDR = [
  ['tc1qw508d6qejxtdg4y5r3zarvary0c5xw7kg3g4ty', 'bc'],  // wrong hrp for mainnet
  ['bc1qw508d6qejxtdg4y5r3zarvary0c5xw7kv8f3t5', 'bc'],  // bad checksum
  ['BC13W508D6QEJXTDG4Y5R3ZARVARY0C5XW7KN40WF2', 'bc'],  // invalid witness version
  ['bc1rw5uspcuh', 'bc'],                                // invalid program length
  ['bc10w508d6qejxtdg4y5r3zarvary0c5xw7kw508d6qejxtdg4y5r3zarvary0c5xw7kw5rljs90', 'bc'],
  ['BC1QR508D6QEJXTDG4Y5R3ZARVARYV98GJ9P', 'bc'],        // bad length for v0
  ['tb1qrp33g0q5c5txsp9arysrx4k6zdkfs4nce4xj0gdcccefvpysxf3q0sL5k7', 'tb'], // mixed case
  ['bc1zw508d6qejxtdg4y5r3zarvaryvqyzf3du', 'bc'],       // >4 bits of zero padding
  ['tb1qrp33g0q5c5txsp9arysrx4k6zdkfs4nce4xj0gdcccefvpysxf3pjxtptv', 'tb'], // non-zero padding
