const corpus = JSON.parse(readFileSync('/tmp/corpus/official-vectors.json', 'utf8'));
let withOutput = 0;
const samples = [];
for (const argv of corpus) {
  const r = spawnSync('/workspace/dataset/test12_executable', argv, { encoding: 'utf8' });
  if ((r.stdout ?? '') !== '') {
    withOutput++;
    if (samples.length < 40) samples.push([argv[1], argv[3], JSON.stringify(r.stdout)]);
  }
  if ((r.stderr ?? '') !== '' || r.status !== 0) {
    console.log('NONZERO', JSON.stringify(argv), r.status, JSON.stringify(r.stderr));
  }
}
console.log(`cases=${corpus.length} withOutput=${withOutput}`);
